#include <pthread.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>

// Global spin lock variable
pthread_spinlock_t spinlock;

// Thread function to simulate lock usage
void *resource_access(void *arg) {
    int ret;
    printf("Thread %lu starting.\n", pthread_self());

    // Attempt to acquire the lock
    if ((ret = pthread_spin_lock(&spinlock)) != 0) {
        fprintf(stderr, "Thread %lu failed to lock: %s\n", pthread_self(), strerror(ret));
        return NULL;
    }

    printf("Thread %lu acquired lock. Working...\n", pthread_self());
    // Critical section work here

    // Release the lock
    if ((ret = pthread_spin_unlock(&spinlock)) != 0) {
        fprintf(stderr, "Thread %lu failed to unlock: %s\n", pthread_self(), strerror(ret));
    }
    return NULL;
}

int main() {
    int ret;
    pthread_t t1;

    // Initialize the spin lock for process-private use
    printf("Attempting to initialize spin lock...\n");
    ret = pthread_spin_init(&spinlock, PTHREAD_PROCESS_PRIVATE);

    if (ret != 0) {
        fprintf(stderr, "Error initializing spin lock: %s\n", strerror(ret));
        return 1;
    }
    printf("Spin lock initialized successfully.\n");

    // Create a thread to use the lock (simulation)
    if (pthread_create(&t1, NULL, resource_access, NULL) != 0) {
        perror("pthread_create");
        pthread_spin_destroy(&spinlock); 
        return 1;
    }

    pthread_join(t1, NULL);

    // Destroy the spin lock
    printf("Attempting to destroy spin lock...\n");
    ret = pthread_spin_destroy(&spinlock);

    if (ret != 0) {
        fprintf(stderr, "Error destroying spin lock: %s\n", strerror(ret));
        return 1;
    }
    printf("Spin lock destroyed successfully.\n");

    return 0;
}
